using System;using System.Windows.Forms;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class TransmissionDiagram {
  static PointF[] Hull(PointF[] input){var points=input.Distinct().OrderBy(p=>p.X).ThenBy(p=>p.Y).ToArray();if(points.Length<3)return points;Func<PointF,PointF,PointF,double> cross=(a,b,c)=>(b.X-a.X)*(c.Y-a.Y)-(b.Y-a.Y)*(c.X-a.X);var lower=new System.Collections.Generic.List<PointF>();foreach(var p in points){while(lower.Count>=2&&cross(lower[lower.Count-2],lower[lower.Count-1],p)<=0)lower.RemoveAt(lower.Count-1);lower.Add(p);}var upper=new System.Collections.Generic.List<PointF>();foreach(var p in points.Reverse()){while(upper.Count>=2&&cross(upper[upper.Count-2],upper[upper.Count-1],p)<=0)upper.RemoveAt(upper.Count-1);upper.Add(p);}lower.RemoveAt(lower.Count-1);upper.RemoveAt(upper.Count-1);return lower.Concat(upper).ToArray();}
  public static void Draw(Graphics g,Result r,double phase,float scale){if(r.Model==null||!r.Model.Valid)return;double ph=r.P.Kind==12?TransmissionSizing.RackPhase(r.P,phase):phase;foreach(var q in r.Model.Parts.Where(p=>p.Role!="housing"&&p.Role!="reference"&&p.Role!="fastener"&&p.Role!="bearing")){TransmissionMotion motion;var m=q.Placement;if(r.TransmissionMotions.TryGetValue(q.Id,out motion))m*=motion.At(ph);using(var pen=new Pen(q.Color,1/scale))using(var fill=new SolidBrush(Color.FromArgb(32,q.Color))){Action<CadLoop,double> loop=(l,z)=>{var points=l.Sample(64).Select(v=>m.Transform(new Point3D(v.X,v.Y,z))).Select(v=>new PointF((float)v.X,(float)v.Y)).ToArray();if(points.Length<3)return;g.FillPolygon(fill,points);g.DrawPolygon(pen,points);};if(q.Loft!=null){var silhouette=Hull(q.Loft.Levels.SelectMany(l=>l.Outer.Sample(64).Select(v=>m.Transform(new Point3D(v.X,v.Y,l.Z)))).Select(v=>new PointF((float)v.X,(float)v.Y)).ToArray());if(silhouette.Length>=3){g.FillPolygon(fill,silhouette);g.DrawPolygon(pen,silhouette);}int n=q.Loft.Levels[0].Outer.Sample(64).Length;for(int i=0;i<n;i+=Math.Max(1,n/8)){int v=i;var line=q.Loft.Levels.Select(l=>{var pt=l.Outer.Sample(64)[v];var p=m.Transform(new Point3D(pt.X,pt.Y,l.Z));return new PointF((float)p.X,(float)p.Y);}).ToArray();if(line.Length>1)g.DrawLines(pen,line);}loop(q.Loft.Levels.First().Outer,q.Loft.Levels.First().Z);loop(q.Loft.Levels.Last().Outer,q.Loft.Levels.Last().Z);}else foreach(var s in q.Sections){loop(s.Outer,s.Bottom);foreach(var hole in s.Holes)loop(hole,s.Bottom);}}}}
 }
 public partial class MainForm {
  CheckBox universalBase;bool robotContext;
  void AddTransmissionFields(){universalBase=new CheckBox{Text="Универсальное основание / рёбра",Width=285,Height=35};universalBase.CheckedChanged+=(s,e)=>{if(updating)return;p.UseUniversalBase=universalBase.Checked;Recalculate(false);};controls.Controls.Add(universalBase);AddNumber("AllowableBendingMPa","Допустимый изгиб, МПа (0 — неизвестно)",0,2000,2,1,false);AddNumber("ServiceFactor","Коэффициент нагрузки K",1,10,2,.1m,false);AddNumber("PressureAngle","Угол давления, °",14.5m,30,2,.5m,false);AddNumber("WormStarts","Заходов червяка",1,8,0,1,false);AddNumber("WormDiameterFactor","Коэффициент диаметра q",6,30,2,.5m,false);AddNumber("Friction","Коэффициент трения μ",0,.5m,3,.005m,false);AddNumber("ShaftAngle","Угол между валами, °",45,135,2,1,false);AddNumber("AxisOffset","Смещение осей, мм",-100,100,2,.5m,false);AddNumber("SpiralAngle","Угол спирали, °",-45,45,2,1,false);AddNumber("GloboidDepth","Глубина огибающей, мм",.1m,30,2,.1m,false);AddNumber("RvPins","RV: пальцев кольца",8,80,0,1,false);AddNumber("CrankCount","RV: кривошипов",2,4,0,1,false);AddNumber("PlanetTeeth","Зубья сателлита A",12,100,0,1,false);AddNumber("SecondPlanetTeeth","Зубья сателлита B",12,100,0,1,false);AddNumber("FixedMember","Фиксация: 0 кольцо / 1 водило / 2 солнце / 3 два входа",0,3,0,1,false);AddNumber("SecondInputRpm","Второй вход, об/мин",-100000,100000,2,1,false);AddNumber("InnerPolePairs","Внутренних полюсных пар",1,30,0,1,false);AddNumber("OuterPolePairs","Наружных полюсных пар",2,100,0,1,false);AddNumber("MagnetThickness","Толщина магнитов, мм",1,30,2,.1m,false);AddNumber("AirGap","Воздушный зазор, мм",.1m,5,2,.1m,false);AddNumber("RackLength","Длина рейки, мм",10,2000,2,1,false);AddNumber("RackTravel","Ход рейки, мм",0,1900,2,1,false);AddNumber("RackPosition","Положение рейки, мм",-950,950,2,1,false);}
  bool TransmissionField(string key){if(p.Kind<5)return false;if(key=="AllowableBendingMPa"||key=="ServiceFactor")return true;if(new[]{"Overall","Module","Thickness","Wall","Clearance","Shaft","OutputShaft","InputRpm","InputTorque","Efficiency","PressureAngle"}.Contains(key))return true;if(new[]{"MotorFrame","MotorMount","MotorPilot","MotorHole","MotorLength"}.Contains(key))return true;if((p.Kind==5||p.Kind==10)&&new[]{"Ratio","WormStarts","WormDiameterFactor","Friction"}.Contains(key))return true;if(p.Kind==10&&key=="GloboidDepth")return true;if((p.Kind==6||p.Kind==9)&&new[]{"Ratio","Teeth","ShaftAngle"}.Contains(key))return true;if(p.Kind==9&&(key=="AxisOffset"||key=="SpiralAngle"))return true;if(p.Kind==7&&new[]{"Ratio","Teeth","RvPins","CrankCount","Radius","Roller","Eccentric","DiscGap"}.Contains(key))return true;if(p.Kind==8&&new[]{"Teeth","PlanetTeeth","SecondPlanetTeeth","Planets","PlanetPin","FixedMember","SecondInputRpm"}.Contains(key))return true;if(p.Kind==11&&new[]{"Radius","InnerPolePairs","OuterPolePairs","MagnetThickness","AirGap"}.Contains(key))return true;if(p.Kind==12&&new[]{"Teeth","RackLength","RackTravel","RackPosition"}.Contains(key))return true;return key.StartsWith("Model")&&modelSettings.Checked;}
 }
}
